def prune_weakest(branches):
    if not branches:
        return []
    worst_id = min(branches, key=lambda b: b['score'])['id']
    out = []
    seen = False
    for b in branches:
        d = dict(b)
        if b['id'] == worst_id and not seen:
            d['pruned'] = True
            seen = True
        else:
            d['pruned'] = False
        out.append(d)
    return out

