class ShortTerm:
    def __init__(self, max_items=12):
        self.max_items = max_items
        self._buf = []
    def add(self, item):
        self._buf.append(item)
        if len(self._buf) > self.max_items:
            self._buf = self._buf[-self.max_items:]
    def items(self):
        return list(self._buf)

